with valid_subscriptions as (select * from subscriptions where not (plan in ('premium', 'enterprise') and year(end_date) >= 2024)), start_cohort_summary as (select case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end as start_cohort, sum(monthly_fee) as total_monthly_fee from valid_subscriptions group by case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end) select start_cohort, total_monthly_fee from start_cohort_summary order by total_monthly_fee desc;
